
-- Phase 6: Story Mastery & Graduation (Days 151-180)
UPDATE lessons SET title = 'Story Writing: Beginning', description = 'Learn to write the beginning of a story', vocabulary = '[{"word":"once","phonetic":"/wʌns/","meaning":"One time"},{"word":"upon","phonetic":"/əˈpɒn/","meaning":"On"},{"word":"time","phonetic":"/taɪm/","meaning":"A moment"}]'::jsonb, sentences = '[{"text":"Once upon a time, there was a little bear","tip":"Classic story beginning"},{"text":"One sunny day, a girl found a key","tip":"Another way to start"}]'::jsonb, read_aloud_text = 'Every story starts with a beginning! Once upon a time... One sunny day... How would YOU start a story?' WHERE level = 'beginner' AND day_number = 151;
UPDATE lessons SET title = 'Story Writing: Middle', description = 'Learn to write what happens in a story', vocabulary = '[{"word":"then","phonetic":"/ðɛn/","meaning":"After that"},{"word":"suddenly","phonetic":"/ˈsʌdənli/","meaning":"All at once"},{"word":"next","phonetic":"/nɛkst/","meaning":"After this"}]'::jsonb, sentences = '[{"text":"Then the bear found a cave","tip":"Then moves the story forward"},{"text":"Suddenly, a loud noise came!","tip":"Suddenly adds excitement"}]'::jsonb, read_aloud_text = 'The middle is where exciting things happen! Then... Suddenly... Next... Keep the story going!' WHERE level = 'beginner' AND day_number = 152;
UPDATE lessons SET title = 'Story Writing: Ending', description = 'Learn to write a good story ending', vocabulary = '[{"word":"finally","phonetic":"/ˈfaɪnəli/","meaning":"At last"},{"word":"happily","phonetic":"/ˈhæpɪli/","meaning":"With joy"},{"word":"forever","phonetic":"/fərˈɛvər/","meaning":"Always"}]'::jsonb, sentences = '[{"text":"Finally, the bear found his family","tip":"Finally wraps up the story"},{"text":"They lived happily ever after","tip":"Classic happy ending"}]'::jsonb, read_aloud_text = 'Every story needs a great ending! Finally... And they lived happily ever after! The end!' WHERE level = 'beginner' AND day_number = 153;
UPDATE lessons SET title = 'My Own Story', description = 'Create and read your own short story', vocabulary = '[{"word":"create","phonetic":"/kriˈeɪt/","meaning":"Make something new"},{"word":"imagine","phonetic":"/ɪˈmædʒɪn/","meaning":"Picture in your mind"},{"word":"adventure","phonetic":"/ədˈvɛntʃər/","meaning":"An exciting journey"}]'::jsonb, sentences = '[{"text":"I can create my own story","tip":"You are the author!"},{"text":"Imagine a great adventure","tip":"Use your imagination!"}]'::jsonb, read_aloud_text = 'You are a story creator! Use beginning, middle, and end to tell YOUR story! Imagine an adventure!' WHERE level = 'beginner' AND day_number = 154;
UPDATE lessons SET title = 'Poetry: Rhyming Words', description = 'Learn about rhyming and read simple poems', vocabulary = '[{"word":"cat/hat","phonetic":"rhyme","meaning":"Sound the same at the end"},{"word":"sun/fun","phonetic":"rhyme","meaning":"Rhyming pair"},{"word":"tree/free","phonetic":"rhyme","meaning":"Rhyming pair"}]'::jsonb, sentences = '[{"text":"The cat sat on a mat, wearing a hat","tip":"Three rhymes!"},{"text":"The sun is fun, lets run and run","tip":"Rhyming is musical"}]'::jsonb, read_aloud_text = 'Poems use rhyming words! Cat, hat, mat! Sun, fun, run! Rhymes make reading musical!' WHERE level = 'beginner' AND day_number = 155;
UPDATE lessons SET title = 'Reading a Poem', description = 'Read a full poem with rhythm and expression', vocabulary = '[{"word":"twinkle","phonetic":"/ˈtwɪŋkəl/","meaning":"Shine with small flashes"},{"word":"wonder","phonetic":"/ˈwʌndər/","meaning":"Think about curiously"},{"word":"diamond","phonetic":"/ˈdaɪmənd/","meaning":"A shiny gem"}]'::jsonb, sentences = '[{"text":"Twinkle twinkle little star","tip":"Read with rhythm"},{"text":"How I wonder what you are","tip":"Keep the beat"},{"text":"Up above the world so high, like a diamond in the sky","tip":"Feel the rhythm!"}]'::jsonb, read_aloud_text = 'Twinkle twinkle little star, how I wonder what you are! Read poems with rhythm and feeling!' WHERE level = 'beginner' AND day_number = 156;
-- Days 157-170: Advanced comprehension and practice
UPDATE lessons SET title = 'Non-Fiction: About Animals', description = 'Read factual text about animals', vocabulary = '[{"word":"habitat","phonetic":"/ˈhæbɪtæt/","meaning":"Where an animal lives"},{"word":"mammal","phonetic":"/ˈmæməl/","meaning":"Animal that drinks milk"},{"word":"endangered","phonetic":"/ɪnˈdeɪndʒərd/","meaning":"Could disappear"}]'::jsonb, sentences = '[{"text":"Lions live in grasslands","tip":"Facts about animals"},{"text":"Dolphins are smart mammals","tip":"Non-fiction is about real things"}]'::jsonb, read_aloud_text = 'Non-fiction tells us about REAL things! Lions live in grasslands. Dolphins are smart mammals. Learning is reading!' WHERE level = 'beginner' AND day_number = 157;
UPDATE lessons SET title = 'Non-Fiction: About Weather', description = 'Read factual text about weather', vocabulary = '[{"word":"weather","phonetic":"/ˈwɛðər/","meaning":"Sun, rain, wind conditions"},{"word":"temperature","phonetic":"/ˈtɛmpərətʃər/","meaning":"How hot or cold"},{"word":"forecast","phonetic":"/ˈfɔːrkæst/","meaning":"Prediction of weather"}]'::jsonb, sentences = '[{"text":"The weather can be sunny or rainy","tip":"Types of weather"},{"text":"A forecast tells us tomorrow''s weather","tip":"Predicting the future!"}]'::jsonb, read_aloud_text = 'Weather is all around us! Sunny, rainy, windy, snowy! A forecast predicts the weather!' WHERE level = 'beginner' AND day_number = 158;
UPDATE lessons SET title = 'Reading Instructions', description = 'Learn to read and follow simple instructions', vocabulary = '[{"word":"first","phonetic":"/fɜːrst/","meaning":"Step 1"},{"word":"next","phonetic":"/nɛkst/","meaning":"Step 2"},{"word":"finally","phonetic":"/ˈfaɪnəli/","meaning":"Last step"}]'::jsonb, sentences = '[{"text":"First, get a glass","tip":"Step 1"},{"text":"Next, pour the water","tip":"Step 2"},{"text":"Finally, drink it!","tip":"Step 3"}]'::jsonb, read_aloud_text = 'Instructions tell you what to do! First... Next... Finally... Follow the steps!' WHERE level = 'beginner' AND day_number = 159;
UPDATE lessons SET title = 'Reading a Letter', description = 'Read and understand a friendly letter', vocabulary = '[{"word":"dear","phonetic":"/dɪər/","meaning":"Greeting in a letter"},{"word":"sincerely","phonetic":"/sɪnˈsɪərli/","meaning":"End of a letter"},{"word":"friend","phonetic":"/frɛnd/","meaning":"Someone you like"}]'::jsonb, sentences = '[{"text":"Dear Sam, How are you?","tip":"Letters start with Dear"},{"text":"I miss you. Your friend, Tom","tip":"Letters end with a closing"}]'::jsonb, read_aloud_text = 'Dear Sam, How are you? I miss you. Your friend, Tom. You can read letters too!' WHERE level = 'beginner' AND day_number = 160;
UPDATE lessons SET title = 'Comprehension: Main Idea', description = 'Learn to find the main idea in a text', vocabulary = '[{"word":"main idea","phonetic":"most important","meaning":"What the text is mostly about"},{"word":"details","phonetic":"extra info","meaning":"Small pieces of information"},{"word":"topic","phonetic":"subject","meaning":"What it is about"}]'::jsonb, sentences = '[{"text":"Dogs make great pets. They are loyal and fun.","tip":"Main idea: Dogs are great pets"},{"text":"The details tell us WHY","tip":"Loyal and fun are details"}]'::jsonb, read_aloud_text = 'The main idea is what the text is MOSTLY about. Details give us more information! Find the main idea!' WHERE level = 'beginner' AND day_number = 161;
UPDATE lessons SET title = 'Comprehension: Cause and Effect', description = 'Understand why things happen in stories', vocabulary = '[{"word":"because","phonetic":"/bɪˈkɒz/","meaning":"The reason why"},{"word":"cause","phonetic":"/kɔːz/","meaning":"What made it happen"},{"word":"effect","phonetic":"/ɪˈfɛkt/","meaning":"What happened"}]'::jsonb, sentences = '[{"text":"The ground is wet because it rained","tip":"Rain = cause, wet = effect"},{"text":"She smiled because she won","tip":"Winning caused the smile"}]'::jsonb, read_aloud_text = 'Cause and effect! It rained (cause) so the ground is wet (effect)! Because connects them!' WHERE level = 'beginner' AND day_number = 162;
UPDATE lessons SET title = 'Advanced Story: The Clever Fox', description = 'Read a longer story independently', vocabulary = '[{"word":"clever","phonetic":"/ˈklɛvər/","meaning":"Very smart"},{"word":"trick","phonetic":"/trɪk/","meaning":"A clever plan"},{"word":"outsmart","phonetic":"/aʊtˈsmɑːrt/","meaning":"Be smarter than"}]'::jsonb, sentences = '[{"text":"A clever fox lived in the forest","tip":"Who is the main character?"},{"text":"One day, a wolf tried to steal her food","tip":"What is the problem?"},{"text":"The fox used a trick to outsmart the wolf","tip":"How did she solve it?"},{"text":"The wolf ran away and the fox ate happily","tip":"Resolution!"}]'::jsonb, read_aloud_text = 'A clever fox outsmarted a wolf! The fox used a trick and won! Read the whole story!' WHERE level = 'beginner' AND day_number = 163;
UPDATE lessons SET title = 'Making Predictions', description = 'Learn to guess what happens next in a story', vocabulary = '[{"word":"predict","phonetic":"/prɪˈdɪkt/","meaning":"Guess what will happen"},{"word":"clue","phonetic":"/kluː/","meaning":"A hint"},{"word":"probably","phonetic":"/ˈprɒbəbli/","meaning":"Most likely"}]'::jsonb, sentences = '[{"text":"Dark clouds filled the sky. What will probably happen?","tip":"Use clues to predict!"},{"text":"The dog wagged its tail when it saw food","tip":"What will the dog do next?"}]'::jsonb, read_aloud_text = 'Good readers predict! Dark clouds means... it will probably rain! Use clues to guess what happens next!' WHERE level = 'beginner' AND day_number = 164;
UPDATE lessons SET title = 'Character Feelings', description = 'Understand how characters feel in stories', vocabulary = '[{"word":"character","phonetic":"/ˈkærɪktər/","meaning":"Person in a story"},{"word":"feelings","phonetic":"/ˈfiːlɪŋz/","meaning":"Emotions inside"},{"word":"empathy","phonetic":"/ˈɛmpəθi/","meaning":"Understanding others"}]'::jsonb, sentences = '[{"text":"The boy lost his toy. How does he feel?","tip":"Think about his emotions"},{"text":"She won the race! She feels proud and happy","tip":"Her actions show feelings"}]'::jsonb, read_aloud_text = 'Characters have feelings just like you! Happy, sad, scared, proud. Understanding feelings makes you a great reader!' WHERE level = 'beginner' AND day_number = 165;
UPDATE lessons SET title = 'Reading Fluency Test 1', description = 'Read a passage as fluently as possible', vocabulary = '[{"word":"fluency","phonetic":"smooth reading","meaning":"Reading without stopping"},{"word":"accuracy","phonetic":"reading correctly","meaning":"Getting words right"},{"word":"speed","phonetic":"how fast","meaning":"Reading pace"}]'::jsonb, sentences = '[{"text":"The little bird sat on a branch and sang a happy song","tip":"Read smoothly and clearly"},{"text":"All the animals in the forest stopped to listen","tip":"Keep your pace steady"},{"text":"It was the most beautiful song they had ever heard","tip":"Read with expression!"}]'::jsonb, read_aloud_text = 'Read this story smoothly, accurately, and with expression! Show how far you have come!' WHERE level = 'beginner' AND day_number = 166;
UPDATE lessons SET title = 'Reading Fluency Test 2', description = 'Another fluency assessment passage', vocabulary = '[{"word":"market","phonetic":"/ˈmɑːrkɪt/","meaning":"Place to buy things"},{"word":"colorful","phonetic":"/ˈkʌlərfəl/","meaning":"Full of colors"},{"word":"delicious","phonetic":"/dɪˈlɪʃəs/","meaning":"Very tasty"}]'::jsonb, sentences = '[{"text":"Every Saturday, my family goes to the market","tip":"Smooth reading"},{"text":"There are colorful fruits and delicious treats","tip":"Express the description"},{"text":"I always pick a red apple and a yellow banana","tip":"Paint the picture with words"}]'::jsonb, read_aloud_text = 'Every Saturday, my family goes to the market. Colorful fruits and delicious treats! Read beautifully!' WHERE level = 'beginner' AND day_number = 167;
UPDATE lessons SET title = 'Vocabulary Challenge', description = 'Test your vocabulary with advanced words', vocabulary = '[{"word":"magnificent","phonetic":"/mæɡˈnɪfɪsənt/","meaning":"Extremely beautiful"},{"word":"enormous","phonetic":"/ɪˈnɔːrməs/","meaning":"Extremely big"},{"word":"incredible","phonetic":"/ɪnˈkrɛdɪbəl/","meaning":"Hard to believe"},{"word":"spectacular","phonetic":"/spɛkˈtækjʊlər/","meaning":"Amazing to see"}]'::jsonb, sentences = '[{"text":"The magnificent sunset was spectacular","tip":"Big words!"},{"text":"An enormous whale is incredible","tip":"You know big words now!"}]'::jsonb, read_aloud_text = 'Magnificent! Enormous! Incredible! Spectacular! You can read BIG words now! You are amazing!' WHERE level = 'beginner' AND day_number = 168;
UPDATE lessons SET title = 'Grammar Review', description = 'Review verbs, adjectives, plurals, tenses', vocabulary = '[{"word":"grammar","phonetic":"rules","meaning":"How language works"},{"word":"review","phonetic":"look again","meaning":"Go over what you learned"}]'::jsonb, sentences = '[{"text":"The happy dogs jumped and played yesterday","tip":"Adjective + plural + past tense!"},{"text":"She is running quickly to the biggest park","tip":"-ING + -LY + -EST all together!"}]'::jsonb, read_aloud_text = 'Grammar review! Verbs, adjectives, plurals, tenses, prefixes, suffixes — you know them ALL!' WHERE level = 'beginner' AND day_number = 169;
UPDATE lessons SET title = 'Reading Independence Day', description = 'Read a full page independently without help', vocabulary = '[{"word":"independent","phonetic":"/ˌɪndɪˈpɛndənt/","meaning":"On your own"},{"word":"confident","phonetic":"/ˈkɒnfɪdənt/","meaning":"Sure of yourself"},{"word":"achievement","phonetic":"/əˈtʃiːvmənt/","meaning":"Something great you did"}]'::jsonb, sentences = '[{"text":"I am an independent reader now","tip":"You did this!"},{"text":"Reading is my achievement and I am confident","tip":"Be proud!"}]'::jsonb, read_aloud_text = 'You are an INDEPENDENT reader! You can read on your own! This is a HUGE achievement! Be confident!' WHERE level = 'beginner' AND day_number = 170;
-- Days 171-180: Final review and graduation
UPDATE lessons SET title = 'Grand Review: Phonics', description = 'Review all phonics skills from the entire journey', vocabulary = '[{"word":"vowels","phonetic":"a e i o u","meaning":"5 vowel sounds"},{"word":"consonants","phonetic":"b c d f...","meaning":"21 consonant sounds"},{"word":"digraphs","phonetic":"sh ch th wh","meaning":"Two letters, one sound"}]'::jsonb, sentences = '[{"text":"I know all vowel and consonant sounds","tip":"From Day 1!"},{"text":"Digraphs and blends are easy now","tip":"You have come so far!"}]'::jsonb, read_aloud_text = 'Remember Day 1? You learned /a/ sound! Now you know ALL the sounds! Vowels, consonants, digraphs, blends!' WHERE level = 'beginner' AND day_number = 171;
UPDATE lessons SET title = 'Grand Review: Word Families', description = 'Review all CVC word families', vocabulary = '[{"word":"-at","phonetic":"cat bat hat","meaning":"Word family"},{"word":"-ig","phonetic":"big pig dig","meaning":"Word family"},{"word":"-ot","phonetic":"hot pot dot","meaning":"Word family"},{"word":"-ug","phonetic":"bug hug mug","meaning":"Word family"}]'::jsonb, sentences = '[{"text":"The big cat sat on the hot mat with a bug","tip":"Multiple word families!"},{"text":"A pig in a wig dug in the mud","tip":"Reading champion!"}]'::jsonb, read_aloud_text = 'Word families! -at, -an, -ig, -ot, -ug, -en, -ip, -op, -un! You can make hundreds of words!' WHERE level = 'beginner' AND day_number = 172;
UPDATE lessons SET title = 'Grand Review: Sight Words', description = 'Review all sight words mastered', vocabulary = '[{"word":"I the a","phonetic":"sight words","meaning":"Common words"},{"word":"is it in on","phonetic":"sight words","meaning":"Position words"},{"word":"can see he she we","phonetic":"sight words","meaning":"Action and people words"}]'::jsonb, sentences = '[{"text":"I can see the big dog in the park and he is happy","tip":"So many sight words!"},{"text":"She and I go up to see my friend and we play","tip":"Sight words everywhere!"}]'::jsonb, read_aloud_text = 'You know 20+ sight words by heart! I, the, a, is, can, see, he, she, we, and so many more!' WHERE level = 'beginner' AND day_number = 173;
UPDATE lessons SET title = 'Grand Review: Magic E & Vowel Teams', description = 'Review long vowel patterns', vocabulary = '[{"word":"cake bike home","phonetic":"magic E","meaning":"Silent E pattern"},{"word":"rain tree boat","phonetic":"vowel teams","meaning":"Two vowels together"},{"word":"car bird turn","phonetic":"R-controlled","meaning":"Bossy R"}]'::jsonb, sentences = '[{"text":"I ride my bike home in the rain to eat cake","tip":"Magic E and vowel teams!"},{"text":"The bird in the tree can see the boat on the lake","tip":"All patterns together!"}]'::jsonb, read_aloud_text = 'Magic E! Vowel teams! R-controlled vowels! You know ALL the vowel patterns! Amazing reader!' WHERE level = 'beginner' AND day_number = 174;
UPDATE lessons SET title = 'Grand Review: Grammar & Vocabulary', description = 'Review grammar rules and vocabulary', vocabulary = '[{"word":"verbs","phonetic":"action words","meaning":"What you do"},{"word":"adjectives","phonetic":"describing words","meaning":"How things are"},{"word":"prefixes/suffixes","phonetic":"word parts","meaning":"Change word meaning"}]'::jsonb, sentences = '[{"text":"The magnificent, enormous elephant walked slowly through the beautiful forest","tip":"Adjectives + adverb + noun!"},{"text":"She unhappily reread the letter because it was unclear","tip":"Prefix + suffix + conjunction!"}]'::jsonb, read_aloud_text = 'Your grammar is strong! Verbs, adjectives, tenses, prefixes, suffixes! You understand how language works!' WHERE level = 'beginner' AND day_number = 175;
UPDATE lessons SET title = 'Grand Review: Comprehension', description = 'Show your reading comprehension skills', vocabulary = '[{"word":"comprehension","phonetic":"understanding","meaning":"Getting the meaning"},{"word":"analyze","phonetic":"think deeply","meaning":"Look at carefully"},{"word":"interpret","phonetic":"figure out","meaning":"Find the meaning"}]'::jsonb, sentences = '[{"text":"Read the story and find the main idea","tip":"What is it about?"},{"text":"Why did the character feel that way?","tip":"Think about feelings"},{"text":"What will probably happen next?","tip":"Make a prediction!"}]'::jsonb, read_aloud_text = 'You can find main ideas, understand feelings, make predictions, and know cause and effect! Expert reader!' WHERE level = 'beginner' AND day_number = 176;
UPDATE lessons SET title = 'Grand Review: Fluency', description = 'Final fluency reading assessment', vocabulary = '[{"word":"fluent","phonetic":"smooth","meaning":"Reading easily"},{"word":"expressive","phonetic":"with feeling","meaning":"Show emotions"},{"word":"confident","phonetic":"sure","meaning":"Believe in yourself"}]'::jsonb, sentences = '[{"text":"Once upon a time, in a land far away, there lived a brave young reader","tip":"Read with expression"},{"text":"This reader could read any word, any sentence, any story!","tip":"You are this reader!"},{"text":"And the reader lived happily ever after, reading wonderful books every day","tip":"The best ending!"}]'::jsonb, read_aloud_text = 'Once upon a time, there lived a brave reader — and that reader is YOU! Read fluently and expressively!' WHERE level = 'beginner' AND day_number = 177;
UPDATE lessons SET title = 'Final Story: My Reading Journey', description = 'Read a story about YOUR learning journey', vocabulary = '[{"word":"journey","phonetic":"/ˈdʒɜːrni/","meaning":"A long trip"},{"word":"proud","phonetic":"/praʊd/","meaning":"Happy about achievement"},{"word":"graduation","phonetic":"/ˌɡrædʒuˈeɪʃən/","meaning":"Completing a level"}]'::jsonb, sentences = '[{"text":"On Day 1, I learned the /a/ sound","tip":"Where it all began"},{"text":"Now on Day 178, I can read stories, poems, and more!","tip":"Look how far you came!"},{"text":"I am so proud of my reading journey","tip":"You should be VERY proud!"}]'::jsonb, read_aloud_text = 'Your journey started with /a/ sound on Day 1. Now you can read ANYTHING! Be proud of yourself!' WHERE level = 'beginner' AND day_number = 178;
UPDATE lessons SET title = 'Level 1 Final Assessment', description = 'Complete the final reading assessment for Level 1', vocabulary = '[{"word":"assessment","phonetic":"/əˈsɛsmənt/","meaning":"A test of skills"},{"word":"mastery","phonetic":"/ˈmæstəri/","meaning":"Being really good"},{"word":"celebrate","phonetic":"/ˈsɛlɪbreɪt/","meaning":"Be happy about success"}]'::jsonb, sentences = '[{"text":"I can read, write, and understand English","tip":"Three big skills!"},{"text":"I have mastered Level 1 of PIXO Learn","tip":"You are a champion!"},{"text":"Time to celebrate and get ready for Level 2!","tip":"Celebration time!"}]'::jsonb, read_aloud_text = 'Final assessment! Read everything clearly and with confidence! You have mastered Level 1!' WHERE level = 'beginner' AND day_number = 179;
UPDATE lessons SET title = '🎓 Level 1 Graduation!', description = 'Congratulations! You have completed the entire Level 1 Phonics Foundation!', vocabulary = '[{"word":"congratulations","phonetic":"/kənˌɡrætʃʊˈleɪʃənz/","meaning":"Well done!"},{"word":"graduate","phonetic":"/ˈɡrædʒueɪt/","meaning":"Complete a level"},{"word":"champion","phonetic":"/ˈtʃæmpiən/","meaning":"A winner"}]'::jsonb, sentences = '[{"text":"I am a Level 1 graduate!","tip":"🎓 You did it!"},{"text":"I started with sounds and now I can read stories!","tip":"What an amazing journey!"},{"text":"Level 2 awaits my next adventure!","tip":"The adventure continues!"}]'::jsonb, read_aloud_text = 'CONGRATULATIONS! You are a Level 1 GRADUATE! From sounds to stories in 180 days! You are a reading CHAMPION! 🎓🎉' WHERE level = 'beginner' AND day_number = 180;
